      /* ── 页内引导式编辑器（步骤 + 字段说明）────────────────────────────────── */

      "providerStep.back": "返回 provider 列表",
      "providerStep.next": "下一步",
      "providerStep.prev": "上一步",
      "providerStep.optional": "可选",
      "providerStep.basic": "基础连接",
      "providerStep.create": "建会话",
      "providerStep.chat": "发消息",
      "providerStep.stop": "停止",
      "providerStep.history": "历史",
      "providerStep.userParams": "用户参数",
      "providerStep.basicDesc": "先告诉平台上游在哪里、怎么认证。这里的 {{user.键名}} 引用的是最后一步「用户参数」里定义的键——认证用的是每个用户自己的凭据，不是你在这里填的。",
      "providerStep.createDesc": "【前置接口】新开一段对话时第一个被调用：平台请求它拿一个会话 id，之后发消息、停止、历史都带着这个 id（模板里的 {{conversationId}} 就是它）。",
      "providerStep.chatDesc": "【核心接口】用户每发一条消息调用一次，响应必须是 SSE 事件流。请求体模板里 {{message}} 是用户输入的文字；下面的「事件映射」告诉平台怎么读懂这个流。",
      "providerStep.stopDesc": "【后置接口 · 可选】用户点「停止生成」时调用。不配置则抽屉不显示停止按钮（对话不受影响，只是不能中途打断）。",
      "providerStep.historyDesc": "【后置接口 · 可选】重新打开抽屉时拉取过往消息。不配置则只显示本次打开后的新消息（上游仍保存完整历史，随时可以补配）。",
      "providerStep.userParamsDesc": "定义每个用户选择这个上游时要填什么（如 agentId / apiKey / mcpToken）。这里的「键」就是前面各步模板里 {{user.键名}} 的来源；勾选「密文」的参数加密存储、接口只回「已配置」。",
      "providerStep.varsTitle": "模板变量（引擎自动替换，不需要配置）",
      "providerStep.varsBuiltin": "{{message}} = 用户输入的文字（只用于发消息请求体）；{{conversationId}} = 建会话接口返回的会话 id（本步拿到的，后续接口都用它）；{{index}} / {{limit}} = 历史查询的分页游标与条数（只用于历史 query）。",
      "providerStep.varsUser": "{{user.键名}} = 用户在抽屉「设置」里自己填的凭据，键名来自「用户参数」步骤的定义。可用在认证头的值、请求体、路径任何位置。",
      "providerStep.hint.baseUrl": "上游的根地址，所有接口的路径都拼在它后面。如 http://stgstplatform.example:8089",
      "providerStep.hint.authHeader": "认证信息放哪个请求头。通常不用改。",
      "providerStep.hint.authValue": "认证头的值模板。如 Bearer {{user.apiKey}}——apiKey 是每个用户自己填的，这里只写「放哪、怎么拼」。",
      "providerStep.hint.successCode": "很多平台 HTTP 200 但业务码失败。两个字段都填才生效：如 code = 0000 表示成功；留空只看 HTTP 状态码。",
      "providerStep.hint.path": "接口路径，以 / 开头，拼在 Base URL 后面。",
      "providerStep.hint.createPath": "建会话的接口路径。",
      "providerStep.hint.conversationIdPath": "建会话响应 JSON 里「会话 id」所在的位置（点路径）。如响应是 {\"code\":\"0000\",\"data\":\"26abc\"} 就填 data——拿到的 26abc 之后会替换所有接口里的 {{conversationId}}。",
      "providerStep.hint.bodyTemplate": "请求体模板（JSON）。整串是一个占位符且用户填的是数字时，会按数字发送（不带引号）。",
      "providerStep.hint.createBody": "建会话要带的参数。如 agent-vendor 要求带 agentId：{\"agentId\": \"{{user.agentId}}\"}。",
      "providerStep.hint.chatBody": "发消息的请求体。{{message}} 是用户输入的文字，{{conversationId}} 是第一步拿到的会话 id。",
      "providerStep.hint.attachments": "勾选后，用户消息带附件时会把附件数组并进请求体的 attachments 字段。",
      "providerStep.hint.stopPath": "停止生成的接口路径，用 {{conversationId}} 指明停哪个会话。",
      "providerStep.hint.deletePath": "删除会话的接口路径（agent-vendor 是 /api/v1/chat/conversation/{id}/delete）。不配置则用户删除会话时只清本地映射、上游留痕。",
      "providerStep.hint.historyPath": "查历史的接口路径。",
      "providerStep.hint.messagesPath": "响应 JSON 里消息数组的位置。如 data。",
      "providerStep.hint.queryTemplate": "分页参数怎么传（JSON）：{{index}} 是游标、{{limit}} 是条数，都由平台传入。",
      "providerStep.hint.fieldsMapping": "每条消息里 id / role / text / time 分别在哪个字段（JSON）。role 为 USER 的算用户消息，其余算助手回复。",
      "providerStep.hint.eventField": "每个 SSE 事件的 JSON 里，表示「这是什么事件」的字段名。如 agent-vendor 是 eventType。",
      "providerStep.hint.token": "文字增量事件：上游的事件名 + 文字内容在哪个字段。流式回复就是靠它逐字上屏。",
      "providerStep.hint.done": "回复完成的事件：事件名 + 完整回复在哪个字段。成功标记（可空）：该字段值是 false 时按失败处理（agent-vendor 的 FINAL_RESULT 就是这种）。",
      "providerStep.hint.error": "上游报错的事件：事件名 + 给用户看的错误文案在哪个字段。",
      "providerStep.hint.tool": "工具调用事件（可空，但强烈建议配）：用户能看见 AI 正在调用什么工具。工具名 / 状态是字段路径，兜底路径在主路径取不到时用。",
      "providerStep.hint.ignore": "要忽略的上游事件名，逗号分隔。如心跳 HEART_BEAT（平台自己发保活，不需要上游的）。",
      "providerStep.hint.paramKey": "参数的键名（字母开头，字母/数字/下划线）。模板里用 {{user.键名}} 引用。",
      "providerStep.hint.paramLabel": "用户在设置卡里看到的显示名。",
      "providerStep.hint.paramSecret": "密文参数加密存储、接口只回「已配置」；明文只在保存与测试的请求里出现一次。",
      "providerStep.hint.paramRequired": "必填参数没填时，用户保存会被拦截。",
