      "providerStep.back": "Back to the provider list",
      "providerStep.next": "Next",
      "providerStep.prev": "Back",
      "providerStep.optional": "optional",
      "providerStep.basic": "Connection",
      "providerStep.create": "Create conversation",
      "providerStep.chat": "Chat",
      "providerStep.stop": "Stop",
      "providerStep.history": "History",
      "providerStep.userParams": "User parameters",
      "providerStep.basicDesc": "Tell the platform where the upstream lives and how it authenticates. {{user.key}} here references the keys defined in the final \"User parameters\" step — authentication uses each user's own credentials, not something you fill in here.",
      "providerStep.createDesc": "[First endpoint called] When a new conversation starts, the platform calls this to obtain a conversation id; chat, stop and history then all carry it (that's what {{conversationId}} in the templates is).",
      "providerStep.chatDesc": "[Core endpoint] Called once per message the user sends; the response must be an SSE event stream. In the body template, {{message}} is the user's text; the event mapping below tells the platform how to read the stream.",
      "providerStep.stopDesc": "[Later endpoint · optional] Called when the user clicks \"Stop generating\". If left unconfigured, the drawer shows no stop button (chat still works; you just can't interrupt mid-stream).",
      "providerStep.historyDesc": "[Later endpoint · optional] Fetches past messages when the drawer reopens. If left unconfigured, only messages from the current session show (the upstream still keeps full history — you can configure this later).",
      "providerStep.userParamsDesc": "Define what each user must fill in when they pick this upstream (e.g. agentId / apiKey / mcpToken). The \"key\" is exactly what {{user.key}} in the earlier templates references; parameters marked \"secret\" are stored encrypted and the API only reports \"configured\".",
      "providerStep.varsTitle": "Template variables (replaced automatically by the engine — nothing to configure)",
      "providerStep.varsBuiltin": "{{message}} = the user's typed text (chat body only); {{conversationId}} = the conversation id returned by the create-conversation endpoint (used by every later endpoint); {{index}} / {{limit}} = the history pagination cursor and page size (history query only).",
      "providerStep.varsUser": "{{user.key}} = credentials the user fills in the drawer's Settings; the key comes from the \"User parameters\" step. Usable anywhere — auth header value, request body, even paths.",
      "providerStep.hint.baseUrl": "The upstream root; every endpoint path is appended to it. e.g. http://stgstplatform.example:8089",
      "providerStep.hint.authHeader": "Which request header carries the authentication. Usually left as is.",
      "providerStep.hint.authValue": "The auth header value template. e.g. Bearer {{user.apiKey}} — apiKey is filled by each user; you only define where it goes and how it's wrapped.",
      "providerStep.hint.successCode": "Many platforms answer HTTP 200 with a failing business code. Both fields must be filled to activate: e.g. code = 0000 means success; leave empty to judge by HTTP status only.",
      "providerStep.hint.path": "The endpoint path, starting with /, appended to the Base URL.",
      "providerStep.hint.createPath": "The create-conversation endpoint path.",
      "providerStep.hint.conversationIdPath": "Where the conversation id sits in the create response JSON (dot path). If the response is {\"code\":\"0000\",\"data\":\"26abc\"}, fill in data — the extracted 26abc then replaces {{conversationId}} everywhere.",
      "providerStep.hint.bodyTemplate": "Request body template (JSON). A value that is exactly one placeholder and renders as a number is sent as a number (unquoted).",
      "providerStep.hint.createBody": "Parameters the create call must carry. e.g. agent-vendor requires agentId: {\"agentId\": \"{{user.agentId}}\"}.",
      "providerStep.hint.chatBody": "The chat request body. {{message}} is the user's text; {{conversationId}} is the id from step 1.",
      "providerStep.hint.attachments": "When checked, messages carrying attachments merge the attachment array into the request body's attachments field.",
      "providerStep.hint.stopPath": "The stop-generation endpoint path, using {{conversationId}} to name the conversation to stop.",
      "providerStep.hint.deletePath": "The delete-conversation endpoint path (agent-vendor: /api/v1/chat/conversation/{id}/delete). Unconfigured, deleting a conversation only clears the local mapping and the upstream keeps its copy.",
      "providerStep.hint.historyPath": "The history endpoint path.",
      "providerStep.hint.messagesPath": "Where the message array sits in the response JSON. e.g. data.",
      "providerStep.hint.queryTemplate": "How pagination is passed (JSON): {{index}} is the cursor and {{limit}} the page size, both supplied by the platform.",
      "providerStep.hint.fieldsMapping": "Which fields of each message hold id / role / text / time (JSON). role USER counts as the user's message; everything else is the assistant's reply.",
      "providerStep.hint.eventField": "The field in each SSE event's JSON that says what kind of event it is. e.g. agent-vendor uses eventType.",
      "providerStep.hint.token": "Text-delta event: the upstream event name plus where the text sits. This is what streams the reply onto the screen.",
      "providerStep.hint.done": "The reply-finished event: its name plus where the full reply sits. Success flag (optional): when that field is false, the outcome is treated as a failure (agent-vendor's FINAL_RESULT works this way).",
      "providerStep.hint.error": "The upstream error event: its name plus where the user-facing error message sits.",
      "providerStep.hint.tool": "Tool-call event (optional but strongly recommended): lets users see which tools the AI is invoking. Tool name / status are field paths; the fallback path applies when the main one yields nothing.",
      "providerStep.hint.ignore": "Upstream event names to ignore, comma-separated. e.g. the HEART_BEAT keepalive (the platform sends its own).",
      "providerStep.hint.paramKey": "The parameter key (starts with a letter; letters/digits/underscore). Referenced in templates as {{user.key}}.",
      "providerStep.hint.paramLabel": "The label users see on the settings card.",
      "providerStep.hint.paramSecret": "Secret parameters are stored encrypted; the API only reports \"configured\". Plaintext appears once, in the save/test request.",
      "providerStep.hint.paramRequired": "Saving is blocked while a required parameter is unfilled.",
      "assistantProviders.deleteTitle": "Delete provider \"{{name}}\"?",
      "assistantProviders.deleteHint": "This also deletes its {{count}} conversation mappings (the upstream keeps its own history); if it is the default provider, the platform returns to the no-default state.",
