      "ciTasks.title": "Repository tasks",
      "ciTasks.hint": "The platform's own Runner clones your repository in a sandbox and runs the command you write. One task states where to clone from, where to run, and what to run.",
      "ciTasks.loadFailed": "Repository tasks could not be loaded",
      "ciTasks.create": "New task",
      "ciTasks.editTitle": "Edit repository task",
      "ciTasks.name": "Task name",
      "ciTasks.namePlaceholder": "smoke",
      "ciTasks.nameRequired": "Task name is required",
      "ciTasks.description": "Description",
      "ciTasks.emptyTitle": "No repository tasks yet",
      "ciTasks.emptyHint": "Create a task with a git URL and a command, and the platform can run your repository's cases — you do not need a CI system of your own first.",
      "ciTasks.codeSource": "Code source",
      "ciTasks.gitUrl": "Git URL",
      "ciTasks.gitUrlRequired": "A git URL is required: the runner needs somewhere to clone from",
      "ciTasks.gitCredential": "Clone credential",
      "ciTasks.gitCredentialNone": "Public repository (no credential)",
      "ciTasks.gitRef": "Branch / ref",
      "ciTasks.noCredentialPool": "This project has no git credential yet. For a private repository, add a read-only token with \"New credential\" right here — no need to leave this page; for a public one, leave the credential unset.",
      "ciTasks.schedulesNewHint": "Schedules attach to a saved task. \"New schedule\" saves this form first (same required-field checks as Save), then opens the schedule form; or save the task and this panel turns into the full one.",
      "ciTasks.runtime": "Runtime",
      "ciTasks.sandboxMode": "Sandbox",
      "ciTasks.sandboxContainer": "Container (default)",
      "ciTasks.sandboxProcess": "Process (I trust this repository's scripts)",
      "ciTasks.sandboxContainerShort": "Container",
      "ciTasks.sandboxProcessShort": "Process",
      "ciTasks.sandboxContainerHint": "Container mode gives filesystem and network isolation, CPU/memory limits and an outbound allowlist. It requires docker on that Runner.",
      "ciTasks.sandboxProcessWarning": "Process mode is not a lighter option, it is a trust declaration: the script shares the Runner's filesystem, can read the clone credential the platform sent it, and gets no outbound allowlist or resource limits. Pick it only if you trust any script in this repository.",
      "ciTasks.workspaceNote": "Both modes use a throwaway working directory: each run gets its own and it is deleted afterwards, so two runs cannot contaminate each other's report. The only thing reused across runs is the dependency cache, keyed by task plus the content hash of the key files.",
      "ciTasks.image": "Image",
      "ciTasks.imageRequired": "Container mode needs an image (or switch to process mode)",
      "ciTasks.runnerLabel": "Partition",
      "ciTasks.labelInvalid": "A partition label is 1–32 lowercase letters, digits or hyphens, starting with a letter or digit",
      "ciTasks.labelNoRunner": "Partition \"{{label}}\" has no online Runner, so triggering will be refused outright. Start a Runner on a machine in that network segment first.",
      "ciTasks.steps": "Command",
      "ciTasks.stepsHint": "One shell script sharing a single process and working directory (the repository root). The platform injects three APITRACK_* variables; do not define your own with those names.",
      "ciTasks.stepsRequired": "A command is required",
      "ciTasks.allureDirFound": "Report directory: {{dir}} (read from --alluredir in the command). After the run the Runner packages that directory and the platform renders the report view itself — no Java, no allure CLI.",
      "ciTasks.allureDirMissing": "No --alluredir found in the command, so this run will produce no report view. Add --alluredir=allure-results to get one (if it lives in your repository's pytest.ini the platform cannot see it, and you can ignore this note).",
      "ciTasks.cache": "Dependency cache",
      "ciTasks.cacheHint": "One path per line, relative to the repository root. The cache key is the content hash of the key files: unchanged files mean a hit. In container mode pip/uv download caches are automatically placed at .cache/pip and .cache/uv; to cache a whole virtual environment, list .venv and create it in the command (e.g. python -m venv .venv && .venv/bin/pip install -r requirements.txt) — the installed .venv is reused on the next run.",
      "ciTasks.cachePaths": "Cached paths",
      "ciTasks.cacheKeyFiles": "Cache key files",
      "ciTasks.env": "Environment variables",
      "ciTasks.envHint": "Stored as plain text, written into the JobSpec and readable in places that end up in logs. The platform no longer masks these values, so keep secrets on the runner machine and have the script read them there.",
      "ciTasks.report": "Report",
      "ciTasks.notify.title": "Notifications",
      "ciTasks.notify.onSuccess": "Notify on success",
      "ciTasks.notify.onFailure": "Notify on failure",
      "ciTasks.notify.hint": "Delivered to the selected channels when a run reaches a terminal state. \"Aborted (Runner lost)\" and \"Timed out\" both count as failure; an explicit cancel is not a result and never notifies. Channels are managed on the Alerts page.",
      "ciTasks.notify.channels": "Channels",
      "ciTasks.notify.channelsPlaceholder": "Pick channels to notify",
      "ciTasks.notify.noChannels": "This project has no notification channels yet — create one on the Alerts page first.",
      "ciTasks.notify.templateTitle": "Title template",
      "ciTasks.notify.templateTitlePlaceholder": "Leave empty for the default title",
      "ciTasks.notify.templateBody": "Body template",
      "ciTasks.notify.templateBodyPlaceholder": "Leave empty for the default body; one item per line",
      "ciTasks.notify.templateHint": "Placeholders: {{taskName}} {{runNumber}} {{status}} {{passedCount}} {{failedCount}} {{skippedCount}} {{total}} {{duration}} {{gitRef}} {{commitSha}} {{reportUrl}} {{trigger}} {{finishedAt}}; unknown ones are kept verbatim. {{reportUrl}} links to the run detail page (a full URL once PUBLIC_BASE_URL is set server-side, otherwise an in-app path).",
      "ciTasks.sdkIngest": "Inject SDK reporting variables",
      "ciTasks.sdkIngestHint": "Injects APITRACK_URL / APITRACK_TOKEN / APITRACK_CI_RUN_ID. If the script has apitrack-sdk installed, case results are reported back and placed in the case tree. This is the only path that writes to the tree: allure results only appear on this run's Cases tab.",
      "ciTasks.limits": "Limits",
      "ciTasks.timeout": "Timeout (minutes)",
      "ciTasks.timeoutInvalid": "Timeout must be a whole number of minutes between 1 and {{max}}",
      "ciTasks.singleConcurrency": "Run serially (one run at a time)",
      "ciTasks.singleConcurrencyHint": "Triggers are **not** rejected: a new run is accepted, queues up, and starts once the previous one finishes. Use this when runs share test data — running them at once makes them step on each other.",
      "ciTasks.singleConcurrencyOffHint": "With this off, the same task can run several times at once (bounded by free Runner slots). Only turn it off when this repository's cases really are independent.",
